<#
.SYNOPSIS
Runs DISM RestoreHealth and returns a structured result.
#>
[CmdletBinding()]
Param([Parameter(Mandatory=$false)][ValidateSet('Object','Json','None')][string]$OutputFormat='Object',[Parameter(Mandatory=$false)][string]$LogPath,[Parameter(Mandatory=$false)][string]$ResultPath,[Parameter(Mandatory=$false)][switch]$Quiet)
function ConvertTo-SingleQuotedArgument{Param([string]$Value)if($null -eq $Value){return "''"};return("'{0}'" -f ($Value -replace "'","''"))}
function Get-RelayParameterText{$parts=@();$parts+=('-OutputFormat {0}' -f (ConvertTo-SingleQuotedArgument $OutputFormat));if($LogPath){$parts+=('-LogPath {0}' -f (ConvertTo-SingleQuotedArgument $LogPath))};if($ResultPath){$parts+=('-ResultPath {0}' -f (ConvertTo-SingleQuotedArgument $ResultPath))};if($Quiet){$parts+='-Quiet'};return($parts -join ' ')}
if([Environment]::Is64BitOperatingSystem -and -not[Environment]::Is64BitProcess){$p=Join-Path $env:WINDIR 'Sysnative\WindowsPowerShell\v1.0\powershell.exe';if(-not(Test-Path $p)){Write-Error '64-bit PowerShell is required, but Sysnative Windows PowerShell was not found.';exit 3};if($PSCommandPath){$cmd=('& {0} {1}' -f (ConvertTo-SingleQuotedArgument $PSCommandPath),(Get-RelayParameterText))}else{$dir=Join-Path $env:TEMP 'AUT-WindowsHealth-Relay';if(-not(Test-Path $dir)){New-Item $dir -ItemType Directory -Force|Out-Null};$relay=Join-Path $dir ('Invoke-DismRestoreHealth-{0}.ps1' -f ([guid]::NewGuid().ToString('N')));Set-Content $relay $MyInvocation.MyCommand.ScriptBlock.ToString() -Encoding UTF8;$cmd=('& {0} {1}' -f (ConvertTo-SingleQuotedArgument $relay),(Get-RelayParameterText))};try{$proc=Start-Process $p -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$cmd) -Wait -PassThru -WindowStyle Hidden;exit $proc.ExitCode}finally{if($relay -and(Test-Path $relay)){Remove-Item $relay -Force -ErrorAction SilentlyContinue}}}
$ScriptName='Invoke-DismRestoreHealth';$Operation='DismRestoreHealth';$Timestamp=Get-Date -Format 'yyyyMMdd-HHmmss';$LogRoot='C:\Temp\Logs';if(-not(Test-Path $LogRoot)){New-Item $LogRoot -ItemType Directory -Force|Out-Null};if([string]::IsNullOrWhiteSpace($LogPath)){$LogPath=Join-Path $LogRoot ('{0}-{1}.log' -f $ScriptName,$Timestamp)};$resultsDir=Join-Path $LogRoot 'results';if(-not(Test-Path $resultsDir)){New-Item $resultsDir -ItemType Directory -Force|Out-Null};if([string]::IsNullOrWhiteSpace($ResultPath)){$ResultPath=Join-Path $resultsDir ('{0}-result-{1}.json' -f $ScriptName,$Timestamp)};$script:LogPath=$LogPath
function Write-Log{Param([string]$Message,[ValidateSet('Debug','Information','Warning','Error')][string]$Level='Information')Add-Content $script:LogPath ('{0} [{1}] [{2}] {3}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$Level,$Operation,$Message) -Encoding UTF8}
function Test-Administrator{$id=[Security.Principal.WindowsIdentity]::GetCurrent();$pr=New-Object Security.Principal.WindowsPrincipal($id);return $pr.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)}
function Get-NativeOutputPath{Param([string]$OperationName,[string]$OutputTimestamp)$ld=Split-Path $script:LogPath -Parent;if([string]::IsNullOrWhiteSpace($ld)){$ld='C:\Temp\Logs'};$sd=Join-Path $ld 'scan-results';if(-not(Test-Path $sd)){New-Item $sd -ItemType Directory -Force|Out-Null};return(Join-Path $sd ('{0}-{1}.txt' -f $OperationName,$OutputTimestamp))}
function Test-OutputPattern{Param([string]$Text,[string]$Pattern)if($null -eq $Text){return $false};$cleanText=$Text.Replace([char]0,'');if($cleanText -match [regex]::Escape($Pattern)){return $true};return(($cleanText -replace '\s','') -match [regex]::Escape(($Pattern -replace '\s','')))}
function New-ErrorObject{Param([string]$Message,[string]$RecommendedAction)return [pscustomobject]@{Target='LocalComputer';Operation=$Operation;Message=$Message;Category='Execution';RecommendedAction=$RecommendedAction}}
function Export-ServicingDiagnostics{Param([datetime]$OperationStartTime,[string]$OutputTimestamp)$artifacts=@();$logDirectory=Split-Path $script:LogPath -Parent;if([string]::IsNullOrWhiteSpace($logDirectory)){$logDirectory='C:\Temp\Logs'};$diagDir=Join-Path $logDirectory 'diagnostics';if(-not(Test-Path $diagDir)){New-Item $diagDir -ItemType Directory -Force|Out-Null};$prefix=Join-Path $diagDir ('{0}-{1}' -f $Operation,$OutputTimestamp);$cbsPath=Join-Path $env:WINDIR 'Logs\CBS\CBS.log';$dismLogPath=Join-Path $env:WINDIR 'Logs\DISM\dism.log';$sessionsPath=Join-Path $env:WINDIR 'servicing\Sessions\Sessions.xml';foreach($item in @(@{Source=$cbsPath;Destination=($prefix+'-CBS-tail.txt');Tail=100},@{Source=$dismLogPath;Destination=($prefix+'-DISM-tail.txt');Tail=100})){try{if(Test-Path $item.Source){Get-Content $item.Source -Tail $item.Tail -ErrorAction Stop|Set-Content $item.Destination -Encoding UTF8;$artifacts+=$item.Destination;Write-Log ('Captured diagnostic {0}.' -f $item.Destination)}}catch{Write-Log ('Unable to capture {0}: {1}' -f $item.Source,$_.Exception.Message) 'Warning'}};try{if(Test-Path $cbsPath){$filtered=$prefix+'-CBS-errors.txt';Get-Content $cbsPath -Tail 2000 -ErrorAction Stop|Select-String -Pattern 'Error|CORRUPT|MISSING|HRESULT'|ForEach-Object{$_.Line}|Set-Content $filtered -Encoding UTF8;$artifacts+=$filtered;Write-Log ('Captured diagnostic {0}.' -f $filtered)}}catch{Write-Log ('Unable to capture filtered CBS diagnostics: {0}' -f $_.Exception.Message) 'Warning'};try{if(Test-Path $sessionsPath){$dest=$prefix+'-Sessions.xml';Copy-Item $sessionsPath $dest -Force -ErrorAction Stop;$artifacts+=$dest;Write-Log ('Captured diagnostic {0}.' -f $dest)}}catch{Write-Log ('Unable to capture Sessions.xml: {0}' -f $_.Exception.Message) 'Warning'};$eventStart=$OperationStartTime.AddMinutes(-5);$queries=@(@{Name='Servicing-Operational';LogName='Microsoft-Windows-Servicing/Operational';Provider=$null},@{Name='System-Servicing';LogName='System';Provider='Microsoft-Windows-Servicing'},@{Name='WindowsUpdateClient-Operational';LogName='Microsoft-Windows-WindowsUpdateClient/Operational';Provider=$null},@{Name='System-WindowsUpdateClient';LogName='System';Provider='Microsoft-Windows-WindowsUpdateClient'});foreach($q in $queries){try{if($null -eq (Get-WinEvent -ListLog $q.LogName -ErrorAction SilentlyContinue)){continue};$filter=@{LogName=$q.LogName;StartTime=$eventStart;Level=@(1,2,3)};if($q.Provider){$filter.ProviderName=$q.Provider};$events=@(Get-WinEvent -FilterHashtable $filter -ErrorAction Stop|Sort-Object TimeCreated -Descending|Select-Object -First 100);if($events.Count -gt 0){$eventPath=$prefix+'-'+$q.Name+'-events.txt';$events|Select-Object TimeCreated,Id,LevelDisplayName,ProviderName,Message|Format-List|Out-String -Width 4096|Set-Content $eventPath -Encoding UTF8;$artifacts+=$eventPath;Write-Log ('Captured diagnostic {0}.' -f $eventPath)}}catch{Write-Log ('Unable to capture {0} events: {1}' -f $q.Name,$_.Exception.Message) 'Warning'}};return @($artifacts)}
function Complete-Script{Param([pscustomobject]$Result)$Result|ConvertTo-Json -Depth 8|Set-Content $Result.ResultPath -Encoding UTF8;Write-Log ('Completed status={0}; exit={1}; nativeExit={2}; rawStatus={3}; recommendedAction={4}; nativeOutput={5}; result={6}.' -f $Result.Status,$Result.ExitCode,$Result.Data.ToolExitCode,$Result.Data.RawStatus,$Result.RecommendedAction,$Result.Data.NativeOutputPath,$Result.ResultPath);switch($OutputFormat){'Json'{$Result|ConvertTo-Json -Depth 8 -Compress}'Object'{Write-Output $Result}'None'{}};exit $Result.ExitCode}
$result=[pscustomobject]@{ScriptName=$ScriptName;Operation=$Operation;Status='Failed';ExitCode=1;Changed=$false;Message='DISM RestoreHealth did not complete.';LogPath=$LogPath;ResultPath=$ResultPath;RecommendedAction='ReviewLog';Data=[pscustomobject]@{ToolExitCode=$null;RawStatus='Unknown';RestoreCompleted=$false;NativeOutputPath=$null;DiagnosticArtifacts=@();Is64BitProcess=[Environment]::Is64BitProcess};Errors=@()}
Write-Log 'Starting DISM RestoreHealth.';if(-not(Test-Administrator)){$result.Status='DependencyMissing';$result.ExitCode=3;$result.Message='Administrative elevation is required.';$result.RecommendedAction='RunElevated';$result.Errors+=New-ErrorObject $result.Message 'RunElevated';Complete-Script $result};$dism=Join-Path $env:WINDIR 'System32\dism.exe';if(-not(Test-Path $dism)){$result.Status='DependencyMissing';$result.ExitCode=3;$result.Message='dism.exe was not found.';$result.RecommendedAction='ReviewWindowsInstallation';$result.Errors+=New-ErrorObject $result.Message 'ReviewWindowsInstallation';Complete-Script $result};$operationStartTime=Get-Date;$out=Get-NativeOutputPath $Operation $Timestamp;$result.Data.NativeOutputPath=$out;Write-Log ('Executing DISM /Online /Cleanup-Image /RestoreHealth; nativeOutput={0}.' -f $out);& $dism /Online /Cleanup-Image /RestoreHealth *> $out;$result.Data.ToolExitCode=$LASTEXITCODE;Write-Log ('DISM RestoreHealth native exit code={0}.' -f $result.Data.ToolExitCode);$text=Get-Content $out -Raw -ErrorAction SilentlyContinue
if($result.Data.ToolExitCode -eq 0 -and ((Test-OutputPattern $text 'The restore operation completed successfully') -or (Test-OutputPattern $text 'The operation completed successfully'))){$result.Status='Changed';$result.ExitCode=0;$result.Changed=$true;$result.Message='DISM RestoreHealth completed successfully.';$result.RecommendedAction='RunSfcScan';$result.Data.RawStatus='Success';$result.Data.RestoreCompleted=$true}elseif($result.Data.ToolExitCode -ne 0){$result.Status='Failed';$result.ExitCode=1;$result.Message=('DISM RestoreHealth failed with native exit code {0}.' -f $result.Data.ToolExitCode);$result.RecommendedAction='ReviewServicingDiagnostics';$result.Data.DiagnosticArtifacts=@(Export-ServicingDiagnostics $operationStartTime $Timestamp);$result.Errors+=New-ErrorObject $result.Message 'ReviewServicingDiagnostics'}else{$result.Message='Unable to determine DISM RestoreHealth status from output.';$result.RecommendedAction='ReviewServicingDiagnostics';$result.Data.DiagnosticArtifacts=@(Export-ServicingDiagnostics $operationStartTime $Timestamp);$result.Errors+=New-ErrorObject $result.Message 'ReviewServicingDiagnostics'};Write-Log ('Classified RestoreHealth as {0}: {1}' -f $result.Data.RawStatus,$result.Message);Complete-Script $result
